import{_ as e,o as s,a as t,b as l}from"./app.DKoEZOcr.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"特殊寄存器访问","link":"/api/SIMD-API/basic_api/special_register_access/special_register_access"},{"text":"GetSaturationFlag(ISASI)","link":"/api/SIMD-API/basic_api/special_register_access/GetSaturationFlag_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/special_register_access/GetSaturationFlag_ISASI.md","filePath":"api/SIMD-API/basic_api/special_register_access/GetSaturationFlag_ISASI.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788255258000}'),i={name:"api/SIMD-API/basic_api/special_register_access/GetSaturationFlag_ISASI.md"};function d(o,a,n,c,r,p){return s(),t("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>GetSaturationFlag(ISASI)</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_common_intf.h&quot;</code>。</p><p>获取<code>mode</code>指定的全局饱和模式的开启状态，该状态通过<a href="SetSaturationFlag_ISASI.html">SetSaturationFlag</a>设置。饱和模式用于处理计算或精度转换过程中结果溢出或出现INF/NAN的场景，详细说明请参考<a href="SetSaturationFlag_ISASI.html#%E5%8A%9F%E8%83%BD%E8%AF%B4%E6%98%8E">SetSaturationFlag功能说明</a>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">SaturationMode</span><span class="w"> </span><span class="n">mode</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">GetSaturationFlag</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>mode</td><td>饱和模式，取值如下：<br>•<code>SaturationMode::FLOAT</code>：浮点数计算和浮点数精度转换的饱和模式，系统默认开启。<br>•<code>SaturationMode::FLOAT8</code>：浮点数精度转换时，控制FP8类型输出为NAN时是否饱和为0，系统默认开启。该模式仅在精度转换接口处于饱和模式时生效，具体请参考<a href="#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">约束说明</a>。<br>•<code>SaturationMode::INT</code>：整数计算的饱和模式，系统默认关闭。<br>•<code>SaturationMode::CAST</code>：浮点数转整数或整数转整数时的精度转换饱和模式，系统默认开启。<br>各模式影响的数据类型请参考<a href="SetSaturationFlag_ISASI.html#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">SetSaturationFlag的数据类型</a>。模板参数无默认值，调用本接口时必须显式指定。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回<code>true</code>表示<code>mode</code>指定的全局饱和模式已开启，返回<code>false</code>表示该模式已关闭。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT支持<code>SaturationMode::FLOAT</code>、<code>SaturationMode::FLOAT8</code>、<code>SaturationMode::INT</code>和<code>SaturationMode::CAST</code>。</li><li>查询<code>SaturationMode::FLOAT8</code>时，返回值仅表示该模式的开启状态。该模式仅在精度转换接口处于饱和模式时生效，可通过全局<code>SaturationMode::FLOAT</code>或单接口<code>satMode</code>进入饱和模式。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持<code>SaturationMode::FLOAT</code>、<code>SaturationMode::INT</code>和<code>SaturationMode::CAST</code>，不支持<code>SaturationMode::FLOAT8</code>。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品支持<code>SaturationMode::FLOAT</code>、<code>SaturationMode::INT</code>和<code>SaturationMode::CAST</code>，不支持<code>SaturationMode::FLOAT8</code>。</li></ul></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>如下示例中查询整数计算的饱和模式是否开启。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">bool</span><span class="w"> </span><span class="n">enableSat</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetSaturationFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">SaturationMode</span><span class="o">::</span><span class="n">INT</span><span class="o">&gt;</span><span class="p">();</span>
</code></pre></div></article></div>`,1)])])}const u=e(i,[["render",d]]);export{A as __pageData,u as default};
